INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich jedes Problem sofort selbst lösen muss?', 2, '[{"text": "Nein", "correct": true, "because": "Eskalation ist oft sinnvoll"}, {"text": "Ja", "correct": false, "because": "Nicht immer machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, Anfragen effizient zu verwalten?', 3, '[{"text": "Ticket-System", "correct": true, "because": "Organisiert und priorisiert"}, {"text": "E-Mail allein", "correct": false, "because": "Unstrukturiert"}, {"text": "Notizzettel", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehme ich bei der Unterstützung von Nutzern?', 5, '[{"text": "Fehlerdiagnose", "correct": true, "because": "Findet Problemursache"}, {"text": "Problemlösung", "correct": true, "because": "Behebt Anliegen"}, {"text": "Hardware-Design", "correct": false, "because": "Nicht primär"}, {"text": "Marketing", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Priorisierung hilft bei Anfragen. b) Jedes Ticket muss sofort gelöst werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dringlichkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Problem für einen Nutzer bearbeite?', 4, '[{"text": "Dokumentation", "correct": false, "because": "Wichtig für Nachverfolgung"}, {"text": "Nutzerbeschreibung", "correct": false, "because": "Hilft bei Diagnose"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Support-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich Anfragen immer telefonisch lösen muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "E-Mail oder Tickets möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um ein Softwareproblem zu beheben?', 3, '[{"text": "Schrittweise Analyse", "correct": true, "because": "Findet Ursache systematisch"}, {"text": "Sofort neustarten", "correct": false, "because": "Nicht immer effektiv"}, {"text": "Ignorieren", "correct": false, "because": "Löst nichts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen meine Unterstützung effektiv?', 5, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Verkürzt Wartezeit"}, {"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelles Tippen", "correct": false, "because": "Sekundär"}, {"text": "Bunte Notizen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Eskalation immer schlecht ist und b) Tickets nur für große Probleme sind. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Eskalation hilft, Tickets für alles"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Support-Ticket zu bearbeiten?', 4, '[{"text": "Problembeschreibung", "correct": false, "because": "Grundlage der Lösung"}, {"text": "Prioritätsstufe", "correct": false, "because": "Bestimmt Reihenfolge"}, {"text": "Bürodeko", "correct": true, "because": "Kein Support-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich jedes Problem selbst lösen?', 2, '[{"text": "Nein", "correct": true, "because": "Weiterleitung ist üblich"}, {"text": "Ja", "correct": false, "because": "Teamarbeit hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei einem Netzwerkproblem wichtig?', 4, '[{"text": "Fehler identifizieren", "correct": true, "because": "Erster Schritt"}, {"text": "Nutzer informieren", "correct": true, "because": "Hält sie auf dem Laufenden"}, {"text": "Alles neu kaufen", "correct": false, "because": "Übertrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Support immer vor Ort sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Remote-Support ist üblich"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem dringenden Anliegen?', 3, '[{"text": "Schnelle Diagnose", "correct": true, "because": "Verkürzt Ausfallzeit"}, {"text": "Lange Erklärung", "correct": false, "because": "Verzögert Lösung"}, {"text": "Warten auf Team", "correct": false, "because": "Zeitkritisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SLA definiert Reaktionszeiten. b) Alle Tickets sind gleich wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prioritäten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Ticket-System?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Dokumentiert Verlauf"}, {"text": "Priorisierung", "correct": true, "because": "Sortiert nach Dringlichkeit"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Systemvorteil"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich Nutzerfragen immer direkt beantworten muss?', 2, '[{"text": "Nein", "correct": true, "because": "Recherche ist erlaubt"}, {"text": "Ja", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten wähle ich bei einem komplexen Problem?', 4, '[{"text": "Eskalation an Experten", "correct": true, "because": "Sichert schnelle Lösung"}, {"text": "Selbst stundenlang suchen", "correct": false, "because": "Ineffizient"}, {"text": "Nutzer warten lassen", "correct": false, "because": "Schlechter Service"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Dokumentation bei der Problemlösung unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Hilft bei Wiederholungen"}, {"text": "Ja", "correct": false, "because": "Dokumentation ist nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Kommunikation bei der Nutzerunterstützung?', 4, '[{"text": "Klarheit schaffen", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelle Lösung", "correct": false, "because": "Nur indirekt"}, {"text": "Hardware verbessern", "correct": false, "because": "Kein Zusammenhang"}]');
